```python
import random

def partition(arr, low, high):
    i = low - 1
    pivot = arr[high]

    for j in range(low, high):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]

    arr[i + 1], arr[high] = arr[high], arr[i + 1]
    return i + 1

def quickselect(arr, k, low=0, high=-1):
    if high == -1:
        high = len(arr) - 1

    if low > high:
        return None

    if low == high:
        return arr[low]

    pivot_index = partition(arr, low, high)

    if pivot_index == k - 1:
        return arr[pivot_index]
    elif pivot_index > k - 1:
        return quickselect(arr, k, low, pivot_index - 1)
    else:
        return quickselect(arr, k, pivot_index + 1, high)
```

Here's an example of how to use the function:

```python
arr = [5, 2, 8, 3, 1]
k = 3
print(quickselect(arr, k))  # Output: 3
```

This function first partitions the array around a pivot element, then recursively selects the k-th smallest element in the left or right partition based on the pivot's position. The median-of-three pivot selection strategy is used to improve the expected time complexity to O(n).
